use slint::{Color, SharedString};

// Re-export FormattedParagraph and TextAlignment generated by slint_build from ui/formatted_text.slint
// so other modules (overlay, engine, main) can import it via `crate::formatter::FormattedParagraph`.
pub use crate::FormattedParagraph;
pub use crate::TextAlignment as TextHorizontalAlignment;

/// Parses a 6-digit (`#RRGGBB`) or 8-digit (`#RRGGBBAA`) hexadecimal color string into a Slint `Color`.
pub fn parse_hex_color(hex: &str) -> Option<Color> {
    let s = hex.trim().strip_prefix('#')?;
    match s.len() {
        6 => {
            let r = u8::from_str_radix(&s[0..2], 16).ok()?;
            let g = u8::from_str_radix(&s[2..4], 16).ok()?;
            let b = u8::from_str_radix(&s[4..6], 16).ok()?;
            Some(Color::from_rgb_u8(r, g, b))
        }
        8 => {
            let r = u8::from_str_radix(&s[0..2], 16).ok()?;
            let g = u8::from_str_radix(&s[2..4], 16).ok()?;
            let b = u8::from_str_radix(&s[4..6], 16).ok()?;
            let a = u8::from_str_radix(&s[6..8], 16).ok()?;
            Some(Color::from_argb_u8(a, r, g, b))
        }
        _ => None,
    }
}

/// Formats a duration in seconds into a human-readable string (e.g., `"45s"`, `"10m"`, `"1h 15m"`).
pub fn format_seconds_human(secs: u32) -> String {
    if secs == 0 {
        "0s".to_string()
    } else if secs < 60 {
        format!("{}s", secs)
    } else if secs >= 3600 {
        let h = secs / 3600;
        let m = (secs % 3600) / 60;
        if m > 0 {
            format!("{}h {}m", h, m)
        } else {
            format!("{}h", h)
        }
    } else if secs % 60 == 0 {
        format!("{}m", secs / 60)
    } else {
        format!("{}m {}s", secs / 60, secs % 60)
    }
}

/// Validates whether the contents of a leading `[...]` bracket block consist exclusively of
/// recognized inline style tokens (`bold`, `italic`, `underline`, `size=8..72`, `color=#hex`).
pub fn is_valid_attr_block(inner: &str) -> bool {
    let tokens: Vec<&str> = inner.split_whitespace().collect();
    if tokens.is_empty() {
        return false;
    }
    for token in tokens {
        match token {
            "bold" | "italic" | "underline" => {}
            s if s.starts_with("size=") => {
                if !s[5..].parse::<u16>().map_or(false, |sz| (8..=72).contains(&sz)) {
                    return false;
                }
            }
            s if s.starts_with("color=") => {
                if parse_hex_color(&s[6..]).is_none() {
                    return false;
                }
            }
            _ => return false,
        }
    }
    true
}

/// Dynamic runtime values used to interpolate `{...}` placeholders in rule messages.
#[derive(Debug, Clone, Default)]
pub struct MessageContext {
    pub rule_name: String,
    pub streak: String,
    pub break_time: String,
    pub app: String,
    pub used: String,
    pub limit: String,
    pub remaining: String,
}

impl MessageContext {
    /// Returns a sample `MessageContext` for live previewing in the Settings UI.
    pub fn sample() -> Self {
        Self {
            rule_name: "Workday Ergonomic Break".to_string(),
            streak: "50m".to_string(),
            break_time: "10m".to_string(),
            app: "steam.exe".to_string(),
            used: "55m".to_string(),
            limit: "60m".to_string(),
            remaining: "5m".to_string(),
        }
    }

    /// Replaces all supported `{...}` placeholders in `template` with their corresponding context values.
    pub fn interpolate(&self, template: &str) -> String {
        template
            .replace("{rule_name}", &self.rule_name)
            .replace("{streak}", &self.streak)
            .replace("{break_time}", &self.break_time)
            .replace("{app}", &self.app)
            .replace("{used}", &self.used)
            .replace("{limit}", &self.limit)
            .replace("{remaining}", &self.remaining)
    }
}

/// Preset color palette mapping hex color codes to their UI combo-box labels.
pub const COLOR_PALETTE: &[(&str, &str)] = &[
    ("#38bdf8", "Color: Sky Blue"),
    ("#10b981", "Color: Emerald"),
    ("#f59e0b", "Color: Amber"),
    ("#f43f5e", "Color: Rose"),
    ("#a855f7", "Color: Purple"),
    ("#6366f1", "Color: Indigo"),
    ("#ffffff", "Color: White"),
];

/// Converts a hex color code (e.g. `"#38bdf8"`) into its human-readable UI combo-box label.
pub fn color_code_to_display(code: &str) -> &'static str {
    COLOR_PALETTE
        .iter()
        .find(|&&(hex, _)| hex.eq_ignore_ascii_case(code))
        .map(|&(_, label)| label)
        .unwrap_or("Color: Default")
}

/// Splits text into lines while normalizing CRLF (`\r\n`) line endings.
fn split_lines(text: &str) -> impl Iterator<Item = &str> {
    text.split('\n').map(|l| l.strip_suffix('\r').unwrap_or(l))
}

/// Applies transformation `f` to the line at `line_idx` (clamped to the last line) and rejoins with `\n`.
fn modify_line_at(raw_text: &str, line_idx: usize, f: impl FnOnce(&str) -> String) -> String {
    let mut lines: Vec<String> = split_lines(raw_text).map(String::from).collect();
    if lines.is_empty() {
        lines.push(String::new());
    }
    let idx = line_idx.min(lines.len() - 1);
    lines[idx] = f(&lines[idx]);
    lines.join("\n")
}

/// Interpolates placeholders and parses line-level headings (`#`, `##`) and `[attr ...]` style blocks
/// into a list of Slint `FormattedParagraph` items.
pub fn parse_message(
    raw_message: &str,
    ctx: &MessageContext,
    default_color: Color,
    alignment: TextHorizontalAlignment,
) -> Vec<FormattedParagraph> {
    let interpolated = ctx.interpolate(raw_message);
    let mut paragraphs = Vec::new();

    let make_para = |text: &str, font_size: f32, font_weight: i32, italic: bool, underline: bool, color: Color| {
        let final_text = if text.is_empty() { "\u{00A0}" } else { text };
        FormattedParagraph {
            text: SharedString::from(final_text),
            font_size,
            font_weight,
            italic,
            underline,
            color,
            alignment,
        }
    };

    for line in split_lines(&interpolated) {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            paragraphs.push(make_para("", 15.0, 400, false, false, default_color));
            continue;
        }

        if let Some(rest) = trimmed.strip_prefix("## ") {
            paragraphs.push(make_para(rest.trim_start(), 20.0, 700, false, false, default_color));
            continue;
        }

        if let Some(rest) = trimmed.strip_prefix("# ") {
            paragraphs.push(make_para(rest.trim_start(), 26.0, 700, false, false, default_color));
            continue;
        }

        // Check for attribute prefix: [attr1 attr2 ...]
        if trimmed.starts_with('[') {
            if let Some(close_idx) = trimmed.find(']') {
                let inner = &trimmed[1..close_idx];
                if is_valid_attr_block(inner) {
                    let tokens: Vec<&str> = inner.split_whitespace().collect();
                    let mut font_size: f32 = 15.0;
                    let mut font_weight: i32 = 400;
                    let mut italic = false;
                    let mut underline = false;
                    let mut text_color = default_color;

                    for token in &tokens {
                        if *token == "bold" {
                            font_weight = 700;
                        } else if *token == "italic" {
                            italic = true;
                        } else if *token == "underline" {
                            underline = true;
                        } else if let Some(size_str) = token.strip_prefix("size=") {
                            if let Ok(sz) = size_str.parse::<u16>() {
                                font_size = sz as f32;
                            }
                        } else if let Some(color_str) = token.strip_prefix("color=") {
                            if let Some(c) = parse_hex_color(color_str) {
                                text_color = c;
                            }
                        }
                    }

                    let content = trimmed[close_idx + 1..].trim_start();
                    paragraphs.push(make_para(content, font_size, font_weight, italic, underline, text_color));
                    continue;
                }
            }
        }

        // Plain line fallback (preserves unrecognized brackets literally)
        paragraphs.push(make_para(trimmed, 15.0, 400, false, false, default_color));
    }

    if paragraphs.is_empty() {
        paragraphs.push(make_para("", 15.0, 400, false, false, default_color));
    }

    paragraphs
}

/// Convenience parser using sample placeholder values and default theme styling for UI live previews.
pub fn parse_formatted_text(raw_message: &str) -> Vec<FormattedParagraph> {
    parse_formatted_text_with_context(raw_message, &MessageContext::sample())
}

/// Convenience parser using specific placeholder context for UI live previews.
pub fn parse_formatted_text_with_context(
    raw_message: &str,
    ctx: &MessageContext,
) -> Vec<FormattedParagraph> {
    let default_color = Color::from_rgb_u8(248, 250, 252); // #f8fafc
    parse_message(
        raw_message,
        ctx,
        default_color,
        TextHorizontalAlignment::Center,
    )
}

/// Represents the detected formatting attributes on a single line of the message editor.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineFormattingStatus {
    pub is_h1: bool,
    pub is_h2: bool,
    pub is_bold: bool,
    pub is_italic: bool,
    pub is_underline: bool,
    pub color_code: String, // e.g. "#38bdf8" or ""
    pub size_val: u32,      // e.g. 18 or 0 (default)
}

impl Default for LineFormattingStatus {
    fn default() -> Self {
        Self {
            is_h1: false,
            is_h2: false,
            is_bold: false,
            is_italic: false,
            is_underline: false,
            color_code: String::new(),
            size_val: 0,
        }
    }
}

/// Inspects the line at `line_idx` and returns its active heading or `[attr ...]` formatting state.
pub fn detect_line_formatting(raw_text: &str, line_idx: usize) -> LineFormattingStatus {
    let lines: Vec<&str> = split_lines(raw_text).collect();
    if line_idx >= lines.len() {
        return LineFormattingStatus::default();
    }
    let line = lines[line_idx].trim();
    let mut status = LineFormattingStatus::default();

    if line.starts_with("# ") {
        status.is_h1 = true;
        return status;
    }
    if line.starts_with("## ") {
        status.is_h2 = true;
        return status;
    }

    if line.starts_with('[') {
        if let Some(close_idx) = line.find(']') {
            let inner = &line[1..close_idx];
            if is_valid_attr_block(inner) {
                for token in inner.split_whitespace() {
                    match token {
                        "bold" => status.is_bold = true,
                        "italic" => status.is_italic = true,
                        "underline" => status.is_underline = true,
                        s if s.starts_with("color=") => {
                            status.color_code = s.strip_prefix("color=").unwrap_or("").to_string();
                        }
                        s if s.starts_with("size=") => {
                            if let Ok(val) = s.strip_prefix("size=").unwrap_or("").parse::<u32>() {
                                status.size_val = val;
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    status
}

/// Toggles or applies a formatting style (`"h1"`, `"h2"`, `"bold"`, `"italic"`, `"underline"`, color, or size)
/// on the specified line index in `raw_text`.
pub fn apply_line_style(raw_text: &str, line_idx: usize, style: &str) -> String {
    modify_line_at(raw_text, line_idx, |target_line| {
        if let Some(&(hex, _)) = COLOR_PALETTE.iter().find(|&&(_, label)| label == style) {
            return toggle_attr(target_line, &format!("color={hex}"));
        }
        if let Some(px_str) = style.strip_prefix("Size: ").and_then(|s| s.strip_suffix("px")) {
            return toggle_attr(target_line, &format!("size={px_str}"));
        }

        match style {
            "h1" => {
                let trimmed = target_line.trim_start();
                if let Some(rest) = trimmed.strip_prefix("# ") {
                    rest.to_string()
                } else {
                    format!("# {}", strip_existing_prefix(target_line))
                }
            }
            "h2" => {
                let trimmed = target_line.trim_start();
                if let Some(rest) = trimmed.strip_prefix("## ") {
                    rest.to_string()
                } else {
                    format!("## {}", strip_existing_prefix(target_line))
                }
            }
            "bold" | "italic" | "underline" => toggle_attr(target_line, style),
            "Color: Default" => {
                strip_attr_prefix(target_line, "color=")
            }
            "Size: Default" => {
                strip_attr_prefix(target_line, "size=")
            }
            s if s.starts_with("color=") || s.starts_with("size=") => toggle_attr(target_line, s),
            _ => target_line.to_string(),
        }
    })
}

/// Appends a `{placeholder}` token to the end of the line at `line_idx`, inserting a space if needed.
pub fn append_placeholder(raw_text: &str, line_idx: usize, placeholder: &str) -> String {
    modify_line_at(raw_text, line_idx, |target_line| {
        let mut line = target_line.to_string();
        if !line.is_empty() && !line.ends_with(' ') {
            line.push(' ');
        }
        line.push_str(placeholder);
        line
    })
}

/// Strips any existing `# `, `## `, or valid `[attr ...]` prefix from `line` and returns the inner content.
fn strip_existing_prefix(line: &str) -> &str {
    let trimmed = line.trim();
    if let Some(rest) = trimmed.strip_prefix("## ") {
        return rest.trim_start();
    }
    if let Some(rest) = trimmed.strip_prefix("# ") {
        return rest.trim_start();
    }
    if trimmed.starts_with('[') {
        if let Some(close_idx) = trimmed.find(']') {
            let inner = &trimmed[1..close_idx];
            if is_valid_attr_block(inner) {
                return trimmed[close_idx + 1..].trim_start();
            }
        }
    }
    trimmed
}

/// Removes all attribute tokens starting with `prefix` (e.g. `"color="` or `"size="`) from a line's `[...]` block.
fn strip_attr_prefix(line: &str, prefix: &str) -> String {
    let trimmed = line.trim();
    if trimmed.starts_with('[') {
        if let Some(close_idx) = trimmed.find(']') {
            let inner = &trimmed[1..close_idx];
            if is_valid_attr_block(inner) {
                let tokens: Vec<String> = inner
                    .split_whitespace()
                    .filter(|t| !t.starts_with(prefix))
                    .map(|s| s.to_string())
                    .collect();
                let content = trimmed[close_idx + 1..].trim_start();
                if tokens.is_empty() {
                    return content.to_string();
                } else {
                    return format!("[{}] {}", tokens.join(" "), content);
                }
            }
        }
    }
    line.to_string()
}

/// Toggles or replaces a single attribute token inside a line's leading `[...]` attribute block.
fn toggle_attr(line: &str, attr: &str) -> String {
    let trimmed = line.trim();
    let stripped_headers = if let Some(rest) = trimmed.strip_prefix("## ") {
        rest.trim_start()
    } else if let Some(rest) = trimmed.strip_prefix("# ") {
        rest.trim_start()
    } else {
        trimmed
    };

    if stripped_headers.starts_with('[') {
        if let Some(close_idx) = stripped_headers.find(']') {
            let inner = &stripped_headers[1..close_idx];
            if is_valid_attr_block(inner) {
                let mut tokens: Vec<String> =
                    inner.split_whitespace().map(|s| s.to_string()).collect();
                let content = stripped_headers[close_idx + 1..].trim_start();

                if let Some(pos) = tokens.iter().position(|t| t == attr) {
                    tokens.remove(pos);
                } else {
                    if attr.starts_with("color=") {
                        tokens.retain(|t| !t.starts_with("color="));
                    } else if attr.starts_with("size=") {
                        tokens.retain(|t| !t.starts_with("size="));
                    }
                    tokens.push(attr.to_string());
                }

                if tokens.is_empty() {
                    return content.to_string();
                } else {
                    return format!("[{}] {}", tokens.join(" "), content);
                }
            }
        }
    }

    format!("[{}] {}", attr, stripped_headers)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Verifies human-readable formatting of seconds across sub-minute, minute, and multi-hour ranges.
    #[test]
    fn test_format_seconds_human() {
        assert_eq!(format_seconds_human(0), "0s");
        assert_eq!(format_seconds_human(30), "30s");
        assert_eq!(format_seconds_human(60), "1m");
        assert_eq!(format_seconds_human(90), "1m 30s");
        assert_eq!(format_seconds_human(3600), "1h");
        assert_eq!(format_seconds_human(3660), "1h 1m");
        assert_eq!(format_seconds_human(7200), "2h");
    }

    /// Verifies that non-attribute bracketed text (e.g. `[Reminder]`) is preserved literally when toggling styles.
    #[test]
    fn test_literal_brackets_not_stripped() {
        let result = apply_line_style("[Reminder] Hello", 0, "bold");
        assert_eq!(result, "[bold] [Reminder] Hello");

        let toggled_off = apply_line_style(&result, 0, "bold");
        assert_eq!(toggled_off, "[Reminder] Hello");
    }

    /// Verifies `detect_line_formatting` accurately reports headings, font weights, colors, and sizes per line.
    #[test]
    fn test_line_formatting_detection() {
        let text = "# Heading 1\n[bold italic] Styled line\n[color=#38bdf8 size=18] Blue line\nPlain line";

        let st0 = detect_line_formatting(text, 0);
        assert!(st0.is_h1);
        assert!(!st0.is_bold);

        let st1 = detect_line_formatting(text, 1);
        assert!(st1.is_bold);
        assert!(st1.is_italic);
        assert!(!st1.is_underline);

        let st2 = detect_line_formatting(text, 2);
        assert_eq!(st2.color_code, "#38bdf8");
        assert_eq!(st2.size_val, 18);

        let st3 = detect_line_formatting(text, 3);
        assert!(!st3.is_bold && !st3.is_italic && st3.color_code.is_empty() && st3.size_val == 0);
    }

    /// Verifies additive toggling and removal of `bold` and `italic` attributes on a line.
    #[test]
    fn test_line_formatting_toggle_bold_italic() {
        let text = "Hello world";
        // Apply bold
        let step1 = apply_line_style(text, 0, "bold");
        assert_eq!(step1, "[bold] Hello world");
        let st1 = detect_line_formatting(&step1, 0);
        assert!(st1.is_bold);

        // Apply italic (additive)
        let step2 = apply_line_style(&step1, 0, "italic");
        assert!(step2.contains("bold") && step2.contains("italic"));
        let st2 = detect_line_formatting(&step2, 0);
        assert!(st2.is_bold && st2.is_italic);

        // Toggle bold off
        let step3 = apply_line_style(&step2, 0, "bold");
        assert_eq!(step3, "[italic] Hello world");
        let st3 = detect_line_formatting(&step3, 0);
        assert!(!st3.is_bold && st3.is_italic);

        // Toggle italic off
        let step4 = apply_line_style(&step3, 0, "italic");
        assert_eq!(step4, "Hello world");
        let st4 = detect_line_formatting(&step4, 0);
        assert!(!st4.is_bold && !st4.is_italic);
    }

    /// Verifies applying and resetting `color=` and `size=` attributes via `"Color: Default"` and `"Size: Default"`.
    #[test]
    fn test_line_formatting_color_and_size() {
        let text = "Text line";
        let with_color = apply_line_style(text, 0, "color=#10b981");
        assert_eq!(with_color, "[color=#10b981] Text line");

        let with_size = apply_line_style(&with_color, 0, "size=20");
        assert!(with_size.contains("color=#10b981") && with_size.contains("size=20"));

        let reset_color = apply_line_style(&with_size, 0, "Color: Default");
        assert_eq!(reset_color, "[size=20] Text line");

        let reset_size = apply_line_style(&reset_color, 0, "Size: Default");
        assert_eq!(reset_size, "Text line");
    }

    /// Verifies toggling `# ` (H1) and `## ` (H2) heading prefixes on and off.
    #[test]
    fn test_h1_h2_toggle() {
        let text = "Heading line";
        let h1 = apply_line_style(text, 0, "h1");
        assert_eq!(h1, "# Heading line");

        // Toggle h1 off
        let plain = apply_line_style(&h1, 0, "h1");
        assert_eq!(plain, "Heading line");

        let h2 = apply_line_style(&plain, 0, "h2");
        assert_eq!(h2, "## Heading line");

        let plain2 = apply_line_style(&h2, 0, "h2");
        assert_eq!(plain2, "Heading line");
    }

    /// Verifies UI combo-box display labels (`"Color: Sky Blue"`, `"Size: 18px"`) map to their underlying attributes.
    #[test]
    fn test_ui_labels_color_and_size() {
        let text = "Hello";
        let with_color = apply_line_style(text, 0, "Color: Sky Blue");
        assert_eq!(with_color, "[color=#38bdf8] Hello");

        let with_size = apply_line_style(text, 0, "Size: 18px");
        assert_eq!(with_size, "[size=18] Hello");
    }

    /// Verifies `is_valid_attr_block` enforces font size bounds (`8..=72`), valid hex colors, and known style tokens.
    #[test]
    fn test_attr_block_validation_boundaries() {
        assert!(is_valid_attr_block("bold italic underline"));
        assert!(is_valid_attr_block("size=8 color=#38bdf8"));
        assert!(is_valid_attr_block("size=72 color=#38bdf8ff"));

        // Invalid cases
        assert!(!is_valid_attr_block(""));
        assert!(!is_valid_attr_block("size=7"));
        assert!(!is_valid_attr_block("size=73"));
        assert!(!is_valid_attr_block("size=abc"));
        assert!(!is_valid_attr_block("color=#12345"));
        assert!(!is_valid_attr_block("color=#gggggg"));
        assert!(!is_valid_attr_block("unknown_token"));
    }

    /// Verifies placeholder insertion spacing and full message parsing with CRLF line endings and empty lines.
    #[test]
    #[allow(non_snake_case)]
    fn test_append_placeholder_And_parse_message() {
        let s1 = append_placeholder("", 0, "{streak}");
        assert_eq!(s1, "{streak}");
        let s2 = append_placeholder(&s1, 0, "{break_time}");
        assert_eq!(s2, "{streak} {break_time}");

        let ctx = MessageContext::sample();
        let paras = parse_formatted_text_with_context("# Header\r\n\r\nActive for {streak}", &ctx);
        assert_eq!(paras.len(), 3);
        assert_eq!(paras[0].text.as_str(), "Header");
        assert_eq!(paras[0].font_size, 26.0);
        assert_eq!(paras[1].text.as_str(), "\u{00A0}");
        assert_eq!(paras[2].text.as_str(), "Active for 50m");
    }
}
